def add_two(a, b):
    """Return a + b."""
    return a + b

def square(x):
    """Return x squared."""
    return x * x

def is_even(n):
    """Return True if n is even."""
    return n % 2 == 0

def max_of_list(xs):
    """Return the largest element of a non-empty list."""
    return max(xs)

def min_of_list(xs):
    """Return the smallest element of a non-empty list."""
    return min(xs)

def sum_list(xs):
    """Return the sum of the numbers in xs."""
    return sum(xs)

def reverse_string(s):
    """Return s reversed."""
    return s[::-1]

def count_char(s, c):
    """Count occurrences of character c in s."""
    return s.count(c)

def factorial(n):
    """Return n! for n >= 0."""
    r = 1
    for i in range(2, n + 1):
        r *= i
    return r

def fibonacci(n):
    """Return the n-th Fibonacci number with f(0)=0, f(1)=1."""
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def is_palindrome(s):
    """Return True if s reads the same backwards."""
    return s == s[::-1]

def count_vowels(s):
    """Count the vowels (aeiou, case-insensitive) in s."""
    return sum(1 for c in s.lower() if c in 'aeiou')

def celsius_to_f(c):
    """Convert Celsius to Fahrenheit."""
    return c * 9 / 5 + 32

def abs_value(x):
    """Return the absolute value of x without using abs()."""
    return -x if x < 0 else x

def clamp(x, lo, hi):
    """Clamp x into the range [lo, hi]."""
    return max(lo, min(hi, x))

def first_char(s):
    """Return the first character of s, or '' if s is empty."""
    return s[:1]

def last_element(xs):
    """Return the last element of xs, or None if empty."""
    return xs[-1] if xs else None

def average(xs):
    """Return the mean of a non-empty list of numbers."""
    return sum(xs) / len(xs)

def dedupe(xs):
    """Remove duplicates from xs, keeping first occurrences in order."""
    seen = set()
    out = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

def flatten(xss):
    """Flatten a list of lists by one level."""
    return [x for xs in xss for x in xs]

def word_count(s):
    """Return the number of whitespace-separated words in s."""
    return len(s.split())

def capitalize_words(s):
    """Capitalize the first letter of every word, words separated by single spaces."""
    return ' '.join(w[:1].upper() + w[1:] for w in s.split(' '))

def is_prime(n):
    """Return True if n is a prime number."""
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True

def gcd(a, b):
    """Return the greatest common divisor of a and b."""
    while b:
        a, b = b, a % b
    return abs(a)

def lcm(a, b):
    """Return the least common multiple of positive a and b."""
    import math
    return a * b // math.gcd(a, b)

def digit_sum(n):
    """Return the sum of the decimal digits of a non-negative integer n."""
    return sum(int(d) for d in str(n))

def count_positive(xs):
    """Count the numbers in xs that are > 0."""
    return sum(1 for x in xs if x > 0)

def filter_even(xs):
    """Return the even numbers of xs in order."""
    return [x for x in xs if x % 2 == 0]

def square_all(xs):
    """Return a list with every element squared."""
    return [x * x for x in xs]

def join_with_comma(xs):
    """Join a list of strings with ', '."""
    return ', '.join(xs)

def char_frequency(s):
    """Return a dict mapping each character in s to its count."""
    d = {}
    for c in s:
        d[c] = d.get(c, 0) + 1
    return d

def merge_dicts(a, b):
    """Return a new dict with keys of a and b; b wins on conflicts."""
    return {**a, **b}

def invert_dict(d):
    """Swap keys and values of a dict with unique values."""
    return {v: k for k, v in d.items()}

def second_largest(xs):
    """Return the second largest distinct value in xs (at least two distinct values)."""
    return sorted(set(xs))[-2]

def chunk(xs, n):
    """Split xs into consecutive chunks of size n (last may be shorter)."""
    return [xs[i:i + n] for i in range(0, len(xs), n)]

def rotate_left(xs, k):
    """Rotate list xs left by k positions."""
    if not xs:
        return []
    k %= len(xs)
    return xs[k:] + xs[:k]

def binary_string(n):
    """Return the binary representation of non-negative n without prefix."""
    return bin(n)[2:]

def from_binary(s):
    """Parse a binary string into an int."""
    return int(s, 2)

def count_words_starting(s, ch):
    """Count words in s that start with character ch."""
    return sum(1 for w in s.split() if w.startswith(ch))

def remove_spaces(s):
    """Remove all space characters from s."""
    return s.replace(' ', '')

def is_sorted(xs):
    """Return True if xs is sorted in non-decreasing order."""
    return all(a <= b for a, b in zip(xs, xs[1:]))

def index_of(xs, x):
    """Return the index of x in xs, or -1 if absent."""
    return xs.index(x) if x in xs else -1

def pairs_sum(xs, target):
    """Return True if two different positions in xs sum to target."""
    seen = set()
    for x in xs:
        if target - x in seen:
            return True
        seen.add(x)
    return False

def title_case(s):
    """Return s in title case using str.title()."""
    return s.title()

def hex_color(r, g, b):
    """Return a lowercase CSS hex color like '#ff0000' for 0-255 r, g, b."""
    return '#%02x%02x%02x' % (r, g, b)

def parse_hex_color(s):
    """Parse '#rrggbb' into an (r, g, b) tuple of ints."""
    s = s.lstrip('#')
    return tuple(int(s[i:i + 2], 16) for i in (0, 2, 4))

def px_to_rem(px, base=16):
    """Convert pixels to rem given a base font size."""
    return px / base

def html_tag(tag, text):
    """Return '<tag>text</tag>'."""
    return f'<{tag}>{text}</{tag}>'

def escape_html(s):
    """Escape &, <, > in s as HTML entities."""
    return s.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')

def strip_tags(s):
    """Remove anything between < and > (inclusive) from s."""
    import re
    return re.sub(r'<[^>]*>', '', s)

def snake_to_camel(s):
    """Convert snake_case to camelCase."""
    parts = s.split('_')
    return parts[0] + ''.join(p.title() for p in parts[1:])

def camel_to_snake(s):
    """Convert camelCase to snake_case."""
    import re
    return re.sub(r'([A-Z])', lambda m: '_' + m.group(1).lower(), s)

def kebab_case(s):
    """Convert a space-separated phrase to lowercase kebab-case."""
    return '-'.join(s.lower().split())

def truncate(s, n):
    """Return s cut to n chars with '...' appended if it was longer than n."""
    return s if len(s) <= n else s[:n] + '...'

def matrix_transpose(m):
    """Transpose a rectangular list-of-lists matrix."""
    return [list(r) for r in zip(*m)]

def count_unique(xs):
    """Return the number of distinct elements."""
    return len(set(xs))

def power_of_two(n):
    """Return True if n is a positive power of two."""
    return n > 0 and n & (n - 1) == 0

def grid_columns(n):
    """Return a CSS grid-template-columns value repeating n equal columns, e.g. 'repeat(3, 1fr)'."""
    return f'repeat({n}, 1fr)'

def spacing_scale(base, n):
    """Return the first n values of a doubling spacing scale starting at base."""
    return [base * 2 ** i for i in range(n)]
